/**
 * Bulk archive for `bulkArchiveIssues`. The live-only predicate keeps an
 * already-archived row's original `archived_at`. Returns the ids this call
 * actually archived.
 */
export async function archiveIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...issueIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.map((row) => row.id as IssueId);
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

