/**
 * Bulk archive from the list multi-select. Unknown, foreign-org and already
 * archived ids are skipped, not failed, because the selection can be stale.
 * Every issue that would be archived is authorized before the first write, so
 * one denial rejects the whole batch with nothing archived or published.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const requested = [...new Set(input.issueIds)];
  const found = new Map(
    (await issueRepo.findIssuesByIds(input.orgId, requested)).map((issue) => [
      issue.id,
      issue,
    ]),
  );

  const candidates: Issue[] = [];
  for (const issueId of requested) {
    const issue = found.get(issueId);
    if (issue === undefined || isArchived(issue)) continue;
    assertCan(actor, "issue:archive", issueResource(issue));
    candidates.push(issue);
  }

  const archivedIds = new Set(
    await issueRepo.archiveIssuesByIds(
      input.orgId,
      candidates.map((issue) => issue.id),
    ),
  );

  const archivedIssues = candidates.filter((issue) =>
    archivedIds.has(issue.id),
  );
  for (const issue of archivedIssues) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: issue.id,
      projectId: issue.projectId,
    });
  }

  return {
    archived: archivedIssues.map((issue) => issue.id),
    skipped: requested.filter((issueId) => !archivedIds.has(issueId)),
  };
}

